#!/usr/bin/env node
import { chmodSync, existsSync, lstatSync, mkdirSync, readFileSync, renameSync, rmSync, statSync, writeFileSync } from 'node:fs';
import path from 'node:path';
import os from 'node:os';
import { createHash } from 'node:crypto';
import { spawnSync } from 'node:child_process';
import { gunzipSync } from 'node:zlib';
import { pathToFileURL } from 'node:url';

const payloadBase64 = "";
const payloadSha256 = "8183af8f52445278d93f6a597b3a3ba6528d868eb70f172453d81fa7fc5193bf";
const frameworkVersion = "0.1.28";

function fail(message, code = 1) {
  process.stderr.write(`[atm-onefile] ${message}\n`);
  process.exit(code);
}

function normalizePortablePath(relativePath) {
  return String(relativePath || '').replace(/\\/g, '/');
}

function resolveFilePath(root, relativePath) {
  const portablePath = normalizePortablePath(relativePath);
  const resolved = path.resolve(root, portablePath);
  const protectedRoot = root.endsWith(path.sep) ? root : root + path.sep;
  if (resolved !== root && !resolved.startsWith(protectedRoot)) {
    throw new Error(`Path escapes extraction root: ${portablePath}`);
  }
  return resolved;
}

function decodePayload(maxOutputLength) {
  const compressed = Buffer.from(payloadBase64, 'base64');
  const digest = createHash('sha256').update(compressed).digest('hex');
  if (digest !== payloadSha256) {
    throw new Error('Embedded payload hash mismatch.');
  }
  return JSON.parse(gunzipSync(compressed, { maxOutputLength }).toString('utf8'));
}

function readPositiveIntEnv(name, fallback) {
  const rawValue = process.env[name];
  if (rawValue === undefined || rawValue === null || rawValue === '') {
    return fallback;
  }
  const parsed = Number(rawValue);
  if (!Number.isFinite(parsed) || parsed <= 0) {
    return fallback;
  }
  return Math.floor(parsed);
}

function sleepMs(durationMs) {
  const waitMs = Math.max(1, Math.floor(durationMs));
  if (typeof SharedArrayBuffer === 'function' && typeof Atomics?.wait === 'function') {
    const signal = new Int32Array(new SharedArrayBuffer(4));
    Atomics.wait(signal, 0, 0, waitMs);
    return;
  }
  const deadline = Date.now() + waitMs;
  while (Date.now() < deadline) {
    // Fallback only for runtimes without Atomics.wait.
  }
}

function resolveCacheBaseRoot() {
  return process.env.ATM_ONEFILE_CACHE_ROOT
    ? path.resolve(process.env.ATM_ONEFILE_CACHE_ROOT)
    : path.join(os.tmpdir(), 'atm-onefile-cache');
}

function extractionLockRoot(cacheRoot) {
  return `${cacheRoot}.lock`;
}

const cacheFilePaths = JSON.parse(gunzipSync(Buffer.from("", 'base64')).toString('utf8'));
function isExtractedRootReady(cacheRoot) {
  try {
    const marker = JSON.parse(readFileSync(path.join(cacheRoot, '.payload-ready.json'), 'utf8'));
    if (marker.payloadSha256 !== payloadSha256) return false;
    const digest = createHash('sha256');
    for (const relativePath of cacheFilePaths) {
      const target = resolveFilePath(cacheRoot, relativePath);
      const info = lstatSync(target);
      if (!info.isFile() || info.isSymbolicLink()) return false;
      const data = readFileSync(target);
      digest.update(JSON.stringify([relativePath, data.length])).update(data);
    }
    return digest.digest('hex') === "c113005c6da35c92b703a5d571bcd8c83bba8e13e6a36bcc347ecadc334b73ae";
  } catch {
    return false;
  }
}

function tryAcquireExtractionLock(lockRoot) {
  try {
    mkdirSync(lockRoot, { recursive: false });
    writeFileSync(path.join(lockRoot, 'owner.json'), JSON.stringify({
      pid: process.pid,
      acquiredAt: new Date().toISOString(),
      payloadSha256
    }, null, 2) + '\n');
    return true;
  } catch (error) {
    if (error && typeof error === 'object' && error.code === 'EEXIST') {
      return false;
    }
    throw error;
  }
}

function releaseExtractionLock(lockRoot) {
  rmSync(lockRoot, { recursive: true, force: true });
}

function renameStagingRoot(stagingRoot, cacheRoot) {
  const retryableCodes = new Set(['EPERM', 'EACCES', 'EBUSY']);
  const attempts = readPositiveIntEnv('ATM_ONEFILE_RENAME_RETRY_ATTEMPTS', 8);
  const delayMs = readPositiveIntEnv('ATM_ONEFILE_RENAME_RETRY_DELAY_MS', 100);
  let lastError = null;
  for (let attempt = 1; attempt <= attempts; attempt += 1) {
    try {
      renameSync(stagingRoot, cacheRoot);
      return;
    } catch (error) {
      lastError = error;
      const code = error && typeof error === 'object' ? error.code : undefined;
      if (process.platform !== 'win32' || !retryableCodes.has(code) || attempt === attempts) {
        throw error;
      }
      sleepMs(delayMs * attempt);
    }
  }
  throw lastError;
}

function extractPayload(cacheRoot) {
  const payload = decodePayload();
  const stagingRoot = `${cacheRoot}.staging-${process.pid}-${Date.now()}`;
  rmSync(stagingRoot, { recursive: true, force: true });
  mkdirSync(stagingRoot, { recursive: true });
  try {
    for (const file of payload.files) {
      const absolutePath = resolveFilePath(stagingRoot, file.path);
      mkdirSync(path.dirname(absolutePath), { recursive: true });
      writeFileSync(absolutePath, Buffer.from(file.dataBase64, 'base64'));
      if (typeof file.mode === 'number' && process.platform !== 'win32') {
        try {
          const current = statSync(absolutePath);
          if ((current.mode & 0o777) !== file.mode) {
            chmodSync(absolutePath, file.mode);
          }
        } catch {
          // ignore mode sync failures
        }
      }
    }
    writeFileSync(path.join(stagingRoot, '.payload-ready.json'), JSON.stringify({
      schemaVersion: payload.schemaVersion,
      generatedAt: payload.generatedAt,
      payloadSha256
    }, null, 2) + '\n');
    rmSync(cacheRoot, { recursive: true, force: true });
    mkdirSync(path.dirname(cacheRoot), { recursive: true });
    // Use rename semantics through copy-less move by relying on same root.
    // On Windows, rename over existing path fails, so cacheRoot is removed above.
    renameStagingRoot(stagingRoot, cacheRoot);
  } finally {
    rmSync(stagingRoot, { recursive: true, force: true });
  }
}

function waitForExtractedRoot(cacheRoot) {
  const lockRoot = extractionLockRoot(cacheRoot);
  const timeoutMs = readPositiveIntEnv('ATM_ONEFILE_EXTRACT_LOCK_TIMEOUT_MS', 15000);
  const pollMs = readPositiveIntEnv('ATM_ONEFILE_EXTRACT_LOCK_POLL_MS', 50);
  const deadline = Date.now() + timeoutMs;
  while (Date.now() < deadline) {
    if (isExtractedRootReady(cacheRoot)) {
      return;
    }
    if (!existsSync(lockRoot) && tryAcquireExtractionLock(lockRoot)) {
      try {
        if (!isExtractedRootReady(cacheRoot)) {
          extractPayload(cacheRoot);
        }
        return;
      } finally {
        releaseExtractionLock(lockRoot);
      }
    }
    sleepMs(pollMs);
  }
  throw new Error(`Timed out waiting for ATM onefile extraction lock for payload ${payloadSha256}.`);
}

function ensureExtractedRoot() {
  const cacheRoot = path.join(resolveCacheBaseRoot(), payloadSha256);
  const lockRoot = extractionLockRoot(cacheRoot);
  if (isExtractedRootReady(cacheRoot)) {
    return cacheRoot;
  }
  mkdirSync(path.dirname(cacheRoot), { recursive: true });
  if (tryAcquireExtractionLock(lockRoot)) {
    try {
      if (!isExtractedRootReady(cacheRoot)) {
        extractPayload(cacheRoot);
      }
    } finally {
      releaseExtractionLock(lockRoot);
    }
  } else {
    waitForExtractedRoot(cacheRoot);
  }
  return cacheRoot;
}

function firstPositionalCommand(args) {
  for (let index = 0; index < args.length; index += 1) {
    const arg = String(args[index] || '');
    if (arg.startsWith('--')) {
      if (arg === '--cwd') {
        index += 1;
      }
      continue;
    }
    return arg;
  }
  return null;
}

const runtimeIdentityReadLimits = {"maxMembers":4096,"maxMemberBytes":33554432,"maxTotalBytes":67108864,"maxPathCharacters":4096,"chunkBytes":65536};
function isRuntimePackageVersion(value         )                  {
  return typeof value === 'string' && /^\d+\.\d+\.\d+(?:-[0-9A-Za-z.-]+)?(?:\+[0-9A-Za-z.-]+)?$/.test(value);
}
function assertNoRuntimeFilePrefixCollisions(paths                  ) {
  const sorted = [...paths].sort();
  for (const file of sorted) {
    const prefix = `${file}/`;
    let low = 0;
    let high = sorted.length;
    while (low < high) {
      const middle = (low + high) >>> 1;
      if (sorted[middle] < prefix) low = middle + 1;
      else high = middle;
    }
    if (sorted[low]?.startsWith(prefix)) throw new Error('file/directory prefix collision');
  }
}
function verifyRuntimeBuildIdentity(
  identity         ,
  packageVersion        ,
  runtimeEntry        ,
  readMember                                                                                     ,
  hash                           ,
  limits                                   = runtimeIdentityReadLimits
) {
  if (!isRuntimePackageVersion(packageVersion) || !identity || typeof identity !== 'object' || Array.isArray(identity)) throw new Error('invalid metadata');
  const record = identity                           ;
  const { buildId, ...content } = record;
  if (record.schemaId !== 'atm.runtimeBuildIdentity.v1' || record.packageName !== '@ai-atomic-framework/cli'
    || record.version !== packageVersion || typeof record.sourceCommit !== 'string' || !/^[a-f0-9]{40}$/.test(record.sourceCommit)
    || typeof record.sourceDigest !== 'string' || !/^[a-f0-9]{64}$/.test(record.sourceDigest)
    || typeof buildId !== 'string' || !/^[a-f0-9]{64}$/.test(buildId) || buildId !== hash(JSON.stringify(content))
    || !Array.isArray(record.files) || record.files.length === 0 || record.files.length > limits.maxMembers) throw new Error('invalid metadata');
  const seen = new Set        ();
  const members                                     = [];
  for (const value of record.files) {
    if (!value || typeof value !== 'object' || Array.isArray(value)) throw new Error('invalid member');
    const file = value                                        ;
    if (typeof file.path !== 'string' || file.path.length > limits.maxPathCharacters || /^[A-Za-z]:/.test(file.path) || file.path.includes('\\') || file.path.includes('\0')
      || file.path.split('/').some(part => part === '' || part === '.' || part === '..') || seen.has(file.path)
      || typeof file.sha256 !== 'string' || !/^[a-f0-9]{64}$/.test(file.sha256)) throw new Error('invalid member');
    seen.add(file.path);
    members.push({ path: file.path, sha256: file.sha256 });
  }
  assertNoRuntimeFilePrefixCollisions(seen);
  let remainingBytes = limits.maxTotalBytes;
  for (const file of members) {
    const member = readMember(file.path, remainingBytes);
    if (!Number.isSafeInteger(member.bytes) || member.bytes < 0 || member.bytes > limits.maxMemberBytes
      || member.bytes > remainingBytes) throw new Error('runtime identity byte budget exceeded');
    remainingBytes -= member.bytes;
    if (member.digest !== file.sha256) throw new Error('runtime bytes differ');
  }
  if (!seen.has(runtimeEntry)) throw new Error('runtime entry missing');
  return { sourceCommit: record.sourceCommit, sourceDigest: record.sourceDigest, buildId };
}
function isVersionRequest(args) {
  return args[0] === '--version' || args[0] === '-v';
}

function writeFastVersionResult() {
  const runtimeBuildIdentity = readFastVersionBuildIdentity();
  const launcherPath = path.resolve(process.argv[1] || 'atm.mjs');
  const runnerSourceDrift = {
    schemaId: 'atm.runnerSourceDrift.v1',
    entrypoint: launcherPath,
    frozenEntrypoint: true,
    runnerPath: launcherPath,
    runnerMtime: null,
    newestSourceMtime: null,
    sourceSeal: { present: true, valid: true, digest: 'sha256:' + payloadSha256 },
    syncRequired: false,
    advisory: 'Standalone onefile runner is sealed to its embedded payload.',
    syncCommand: null
  };
  const runnerMode = {
    schemaId: 'atm.runnerMode.v1',
    mode: 'frozen',
    entrypoint: launcherPath,
    sourceDrift: runnerSourceDrift,
    normalGovernanceCommand: 'node atm.mjs ...',
    sourceFirstCommand: null,
    sourceFirstOnlyWhen: null,
    syncCommand: null,
    frozenRunnerSources: [launcherPath],
    guidance: 'This standalone onefile runner is sealed to its embedded payload.'
  };
  const result = {
    ok: true,
    command: 'version',
    mode: 'standalone',
    cwd: process.cwd(),
    messages: [{ level: 'info', code: 'ATM_CLI_VERSION', text: 'ATM framework version ' + frameworkVersion + '.', data: {} }],
    evidence: { frameworkVersion, runnerMode, runnerSourceDrift, runtimeBuildIdentity },
    nextAction: null,
    taskIntent: null,
    userNotice: null,
    runnerMode,
    frameworkReport: null,
    frameworkClaim: null,
    evidenceSummary: null,
    guardReport: null,
    taskflowReadiness: null,
    commitBundle: null,
    skillGrowth: null,
    laneSession: null,
    severity: 'success',
    exitCode: 0,
    blocking: false,
    diagnostics: { errorCodes: [], warningCodes: [], infoCodes: ['ATM_CLI_VERSION'] }
  };
  process.stdout.write(JSON.stringify(result) + '\n');
}

function isCanonicalPayloadBase64(value) {
  if (typeof value !== 'string' || value.length % 4 !== 0 || !/^[A-Za-z0-9+/]*={0,2}$/.test(value)) return false;
  const alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  return !(value.endsWith('==') && (alphabet.indexOf(value.at(-3)) & 15) !== 0)
    && !(value.endsWith('=') && !value.endsWith('==') && (alphabet.indexOf(value.at(-2)) & 3) !== 0);
}

function readFastVersionBuildIdentity() {
  // Verify only embedded bytes. No extraction, filesystem reads, CLI imports,
  // ancestor package metadata or environment-supplied provenance is involved.
  if (typeof payloadBase64 !== 'string' || payloadBase64.length > Math.ceil(16 * 1024 * 1024 / 3) * 4) throw new Error('Onefile compressed payload budget exceeded.');
  if (!isCanonicalPayloadBase64(payloadBase64)) throw new Error('Invalid compressed payload encoding.');
  const compressedBytes = payloadBase64.length / 4 * 3 - (payloadBase64.endsWith('==') ? 2 : payloadBase64.endsWith('=') ? 1 : 0);
  if (compressedBytes > 16 * 1024 * 1024) throw new Error('Onefile compressed payload budget exceeded.');
  const payload = decodePayload(128 * 1024 * 1024);
  const base = { schemaId: 'atm.runtimeIdentity.v1', packageName: '@ai-atomic-framework/cli', executionMode: 'distribution', version: isRuntimePackageVersion(frameworkVersion) ? frameworkVersion : null,
    sourceCommit: null, sourceDigest: null, buildId: null };
  try {
    if (payload?.schemaVersion !== 'atm.onefilePayload.v0.1' || !Array.isArray(payload.files) || payload.files.length > 4096) throw new Error('Invalid payload members.');
    const members = new Map();
    let totalBytes = 0;
    for (const file of payload.files) {
      if (!file || typeof file !== 'object' || Array.isArray(file) || typeof file.path !== 'string' || file.path.length > runtimeIdentityReadLimits.maxPathCharacters
        || /^[A-Za-z]:/.test(file.path) || file.path.includes('\\') || file.path.includes('\0') || file.path.split('/').some(part => !part || part === '.' || part === '..')
        || members.has(file.path) || !Number.isInteger(file.mode) || file.mode < 0 || file.mode > 511
        || typeof file.dataBase64 !== 'string' || file.dataBase64.length > Math.ceil(runtimeIdentityReadLimits.maxMemberBytes / 3) * 4
        || !isCanonicalPayloadBase64(file.dataBase64)) throw new Error('Invalid payload member.');
      const bytes = file.dataBase64.length / 4 * 3 - (file.dataBase64.endsWith('==') ? 2 : file.dataBase64.endsWith('=') ? 1 : 0);
      if (bytes > runtimeIdentityReadLimits.maxMemberBytes || (totalBytes += bytes) > runtimeIdentityReadLimits.maxTotalBytes) throw new Error('Payload member byte budget exceeded.');
      members.set(file.path, { encoded: file.dataBase64, bytes });
    }
    assertNoRuntimeFilePrefixCollisions(members.keys());
    // These are the real metadata caller locations for version and doctor.
    // A nearer package boundary would stop the filesystem resolver before it
    // reaches packages/cli/package.json, even if the inner JSON is malformed.
    for (const entry of ['atm.js', 'commands/doctor/run-doctor.js']) {
      const parts = entry.split('/');
      for (let count = 0; count < parts.length; count++) {
        const directory = parts.slice(0, count).join('/');
        const boundary = 'packages/cli/dist/' + (directory ? directory + '/' : '') + 'package.json';
        if (members.has(boundary) || [...members.keys()].some(member => member.startsWith(boundary + '/'))) throw new Error('Unexpected embedded package boundary.');
      }
    }
    const read = (relative, limit) => {
      const member = members.get(relative);
      if (!member || member.bytes > limit) throw new Error('Missing or oversized payload member.');
      const bytes = Buffer.from(member.encoded, 'base64');
      if (bytes.toString('base64') !== member.encoded) throw new Error('Noncanonical base64 member.');
      return bytes;
    };
    const identityPath = 'packages/cli/dist/build-identity.json';
    if (!members.has(identityPath)) return { ...base, status: 'unavailable' };
    const pkg = JSON.parse(read('packages/cli/package.json', 1024 * 1024).toString('utf8'));
    if (!pkg || Array.isArray(pkg) || pkg.name !== base.packageName || pkg.version !== frameworkVersion) throw new Error('Embedded package mismatch.');
    const identity = JSON.parse(read(identityPath, 1024 * 1024).toString('utf8'));
    const hash = value => createHash('sha256').update(value).digest('hex');
    const verified = verifyRuntimeBuildIdentity(identity, pkg.version, 'atm.js', (relative, remaining) => {
      const bytes = read('packages/cli/dist/' + relative, Math.min(runtimeIdentityReadLimits.maxMemberBytes, remaining));
      return { digest: hash(bytes), bytes: bytes.length };
    }, hash);
    return { ...base, status: 'verified', ...verified };
  } catch {
    return { ...base, status: 'mismatch' };
  }
}

async function run() {
  try {
    const userArgs = process.argv.slice(2);
    if (isVersionRequest(userArgs)) {
      writeFastVersionResult();
      return;
    }
    const extractedRoot = ensureExtractedRoot();
    const distEntrypoint = path.join(extractedRoot, 'packages', 'cli', 'dist', 'atm.js');
    const sourceEntrypoint = path.join(extractedRoot, 'packages', 'cli', 'src', 'atm.ts');
    const sourceCommandMarker = path.join(extractedRoot, 'packages', 'cli', 'src', 'commands', 'atomize.ts');
    const stableEntrypoint = path.join(extractedRoot, 'atm.mjs');
    const sourceEntrypointReady = existsSync(sourceEntrypoint) && existsSync(sourceCommandMarker);
    const entrypoint = existsSync(distEntrypoint)
      ? distEntrypoint
      : sourceEntrypointReady ? sourceEntrypoint : stableEntrypoint;
    if (!existsSync(entrypoint)) {
      fail('Extracted payload is missing an ATM runtime entrypoint.');
      return;
    }
    const commandName = firstPositionalCommand(userArgs);
    const hasExplicitCwd = userArgs.includes('--cwd');
    const shouldUseExtractedFrameworkCwd = commandName === 'self-host-alpha' && hasExplicitCwd === false;
    const forwardedArgs = shouldUseExtractedFrameworkCwd
      ? [...userArgs, '--cwd', extractedRoot]
      : userArgs;
    Object.assign(process.env, {
      ATM_ONEFILE_RUNTIME: '1',
      ATM_ONEFILE_LAUNCHER_PATH: path.resolve(process.argv[1] || ''),
      ATM_ONEFILE_PAYLOAD_SHA256: payloadSha256,
      ATM_ONEFILE_EXTRACTED_ROOT: extractedRoot
    });

    if (entrypoint === distEntrypoint) {
      // The extracted dist is already a valid ESM CLI. Running it in-process
      // removes one Node startup from every warm onefile invocation.
      const previousCwd = process.cwd();
      try {
        if (shouldUseExtractedFrameworkCwd) {
          process.chdir(extractedRoot);
        }
        const { runCli } = await import(pathToFileURL(distEntrypoint).href);
        process.exitCode = await runCli(forwardedArgs);
      } finally {
        if (process.cwd() !== previousCwd) {
          process.chdir(previousCwd);
        }
      }
      return;
    }

    const nodeArgs = entrypoint === sourceEntrypoint
      ? ['--strip-types', entrypoint, ...forwardedArgs]
      : [entrypoint, ...forwardedArgs];
    const child = spawnSync(process.execPath, nodeArgs, {
      cwd: shouldUseExtractedFrameworkCwd ? extractedRoot : process.cwd(),
      stdio: 'inherit',
      env: process.env,
      windowsHide: true
    });
    if (child.error) {
      fail(`Failed to execute embedded ATM runtime: ${child.error.message}`);
      return;
    }
    process.exitCode = child.status ?? 1;
  } catch (error) {
    fail(error instanceof Error ? error.message : String(error));
  }
}

await run();
